function buildHighSchoolShortstopExecution(match, situation, choice, sample) {
  const handoff = match.groundBallInPlayState;
  if (!Number.isFinite(sample) || sample < 0 || sample >= 1) throw new Error("Invalid SS execution sample");
  assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "SS", "player");
  if (situation.playerPosition !== "游擊手" || !handoff.supported) throw new Error("Invalid SS production context");
  const secureResolution = resolveHighSchoolCanonicalSecure(match, handoff, sample);
  const input = getHighSchoolControlledDecisionInput(match, { ...handoff, secureResolution });
  const opportunity = DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input);
  const controlled = opportunity.status === "controlledDecision";
  const selection = controlled ? DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, choice.routeId, input) : null;
  const thrown = selection ? DefensiveDecisionThrowFoundation.resolveThrow({ input, opportunity, selection,
    capabilities: { defenderId: "player", arm: situation.playerCapabilities.arm, throwing: situation.playerCapabilities.throwing },
    transferState: secureResolution.secureQuality === "bobbleButControlled" ? "delayed" : "ready" }) : null;
  const swing = (sample - 0.5) * 4;
  const receiver = selection?.route.receiverPosition
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], selection.route.receiverPosition) : null;
  const receiverCapabilities = receiver ? getDefensiveSimulationCapability(receiver, receiver.position, match) : {};
  const receiverReady = Boolean(receiver && (Number(receiverCapabilities.fielding) || 5) + swing >= 3.2);
  input.receiverState = { receiverId: receiver?.id || null, ready: receiverReady, atBase: true, tagAvailable: receiverReady, tagDelay: 1 };
  const decisionThrowState = { opportunity, preControlIntent: choice.routeId, selection, activeSelection: selection, throwResolution: thrown };
  // Failed acquisition has no controlled decision or throw. Preserve the existing
  // Foundation's no-contest diagnostic so lifecycle recovery still has an owner.
  let runnerThrowTiming = selection ? null : DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({
    stage: decisionThrowState, runnerState: null, windowState: "expired", receiverFact: "unavailable" });
  let firstLegSettlement = null;
  if (selection) {
    const timingArgs = { input, opportunity, selection, throwResolution: thrown,
      runnerState: input.runnerPhysicalStates.find(r => r.runnerId === selection.route.targetRunnerId),
      receiverState: input.receiverState, resolveThirdOut: resolveHighSchoolThirdOutIntegrity };
    runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.resolveTiming(timingArgs);
    firstLegSettlement = DefensiveRunnerThrowSettlementFoundation.deriveSettlement({ ...timingArgs, timing: runnerThrowTiming });
  }
  const firstOut = firstLegSettlement?.outRecorded === true;
  const continuationWindow = handoff.timingWindows.relayToFirstWindow.state;
  const isDoublePlay = choice.infieldRoute === "doublePlay";
  // Relay completion reuses the established 2B/SS receive-turn-deliver model.
  const relay = resolveInfieldRelayToFirst(situation, firstOut, sample, continuationWindow, receiverCapabilities);
  const secondOut = isDoublePlay && firstOut && situation.outs < 2 && relay.secondOutAvailable;
  const retirements = firstOut ? [{ runnerId: selection.route.targetRunnerId, targetBase: selection.route.targetBase,
    outType: firstLegSettlement.playType === "batterRunner" ? "batterRunnerBeforeFirst" : firstLegSettlement.playType === "force" ? "force" : "nonForceTag", sequence: 1 }] : [];
  if (secondOut) retirements.push({ runnerId: situation.batterId, targetBase: "first", outType: "batterRunnerBeforeFirst", sequence: 2 });
  // Complete all committed actors after the first-leg contest. The existing force
  // owner accounts for in-transit runners, collisions, and force removal after outs.
  const runnerSettlement = ForceAdvancement.settleForceAdvancement({ forceChain: situation.forceChain,
    movementIntents: situation.movementIntents, retirements });
  const error = (secureResolution.attemptAvailable && !secureResolution.secured) || thrown?.throwQuality === "offline";
  const resultCode = secondOut ? "twoOuts" : firstOut ? "oneOut" : error ? "error" : "zeroOuts";
  const detailedResult = secondOut ? "completedDoublePlay" : firstOut ? (isDoublePlay ? "secondStageExpired" : "cleanOut")
    : error ? (secureResolution.secured ? "inaccurateThrow" : "fieldingError") : !secureResolution.secured ? "lateFielding"
      : choice.infieldRoute === "controlledNoThrow" ? "controlledNoThrow" : "lateThrow";
  const primaryCause = !secureResolution.secured ? "playerFieldingControl" : thrown?.throwQuality === "offline" ? "playerFirstThrow"
    : !receiverReady && selection?.route.action !== "holdBall"
      ? selection?.route.receiverPosition === "1B" ? "teammateFirstBaseReceive" : selection?.route.receiverPosition === "C" ? "teammateHomeReceive" : "teammatePivot"
      : isDoublePlay && firstOut && !relay.turn && situation.batterSpeed < 8 && continuationWindow !== "narrow" ? "teammatePivot"
        : isDoublePlay && firstOut && relay.turn && !relay.firstBaseReceive ? "teammateFirstBaseReceive"
          : choice.infieldRoute === "controlledNoThrow" ? "balancedExecution"
            : !firstOut || (isDoublePlay && !secondOut) ? "timingWindow" : "balancedExecution";
  const resolution = attachDefensiveOutcomeExplanation(situation, choice, {
    familyId: "infield", route: choice.infieldRoute, routeId: choice.routeId, initialRoute: choice.routeId, activeRoute: choice.routeId,
    playerRole: "initiator", responsibility: situation.responsibility, resultCode, detailedResult,
    tier: secondOut ? "strong" : firstOut || choice.infieldRoute === "controlledNoThrow" ? "mixed" : "failure",
    decisionQuality: choice.advisable === "strong" ? "strong" : choice.advisable === "aggressive" ? "aggressive" : choice.advisable === "conservative" ? "conservative" : "reasonable",
    executionQuality: firstOut ? (isDoublePlay && !secondOut ? "partial" : "complete") : error ? "misplay" : choice.infieldRoute === "controlledNoThrow" ? "controlled" : "late",
    runnerSettlement, runnerSettlementIdentity: situation.runnerSettlementIdentity, outsCreated: runnerSettlement.outsCreated,
    runnerChanges: runnerSettlement.runnerChanges, runnersAfter: runnerSettlement.runnersAfter,
    scoringRunnerIds: runnerSettlement.scoringRunnerIds, runsAllowed: runnerSettlement.runsAllowed, error,
    primaryCause, secondaryCause: "", responsibleActor: primaryCause.startsWith("teammate") ? "teammate" : primaryCause === "timingWindow" ? "timingWindow" : "player",
    playerResponsibility: error ? "major" : "handled", teammateResponsibility: primaryCause.startsWith("teammate") ? "major" : isDoublePlay ? "shared" : "none",
    causeExplanation: primaryCause === "teammatePivot" ? "傳球的接球端未完成接球或轉傳；二壘手與游擊手的責任分開記錄。"
      : primaryCause === "teammateFirstBaseReceive" ? "傳球已進入一壘接球位置，但一壘手未完成接球；傳球與接球責任分開記錄。" : getSecondBaseCauseExplanation(primaryCause, ""),
    playerLeg: { reach: handoff.defensiveAccess.reachResolution.reached ? "completed" : "late",
      control: secureResolution.secured ? "completed" : "failed", transfer: thrown?.releaseQuality === "delayedRelease" ? "delayed" : controlled ? "completed" : "notReached",
      firstThrow: thrown?.throwAttempted ? thrown.throwQuality === "offline" ? "failed" : "completed" : "notAttempted" },
    teammateLeg: { receiver: receiverReady ? "completed" : "notReached", ...(isDoublePlay ? {
      secondBaseReceive: relay.receive ? "completed" : "notCompleted", secondBasePivot: relay.turn ? "completed" : "notCompleted",
      secondBaseSecondThrow: relay.turn ? "completed" : "notCompleted", firstBaseReceive: relay.firstBaseReceive ? "completed" : "notCompleted" } : {}) },
    firstLegState: { status: firstOut ? "completed" : "failed", targetBase: selection?.route.targetBase || null },
    continuationState: { status: secondOut ? "completed" : firstOut && isDoublePlay ? "windowClosed" : "settledByActorOutcomes", targetBase: isDoublePlay ? "first" : null, window: continuationWindow },
    timingResolution: { firstLeg: runnerThrowTiming, firstLegSettlement, relayToFirstWindow: continuationWindow },
    ballContext: situation.ballContext.type, ballDirection: situation.ballDirection, ballDepth: situation.ballDepth,
    batterSpeed: situation.batterSpeed, runnerSpeed: Math.max(...situation.runnerSpeeds.filter(Number.isFinite), 0),
    ...situation.playerCapabilities, firstStage: secureResolution.margin ?? handoff.defensiveAccess.reachResolution.margin,
    secondStage: thrown?.accuracyMargin ?? 0, returnTiming: 0, windows: situation.windows
  });
  return { sample, choice: { routeId: choice.routeId, matchDecision: choice.matchDecision }, secureResolution,
    decisionThrowState,
    runnerThrowTiming, resolution: attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) };
}

function getDefensiveSimulationCapability(subject = player, position = player.primaryPosition, matchContext = subject?.highSchoolMatch) {
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ fielding: subject.defense, reaction: subject.defense, range: subject.defense, arm: subject.arm, throwing: subject.arm, decision: Math.round((subject.defense + subject.contact) / 2) });
  }
  const rawSkills = subject.baseballSkills || {};
  const activeMatch = matchContext || (subject === player ? player.highSchoolMatch : null);
  const audit = getDevelopmentMatchPositionTestCapabilityAudit(subject, activeMatch);
  const skills = audit.active && !activeMatch?.completed
    ? Object.fromEntries(Object.keys(rawSkills).map(skill => [skill, audit.skills[skill]?.effective ?? rawSkills[skill]]))
    : rawSkills;
  const effectivePosition = audit.active ? audit.position : position;
  const positionTools = {
    "內野手": ["catching", "reaction", "throwing"],
    "外野手": ["catching", "range", "armStrength"],
    "捕手": ["blocking", "gameCalling", "throwing"],
    "投手": ["control", "reaction", "throwing"]
  }[position] || ["catching", "reaction", "throwing"];
  const values = positionTools.map(key => Number(skills[key]) || 0);
  const reactionSkill = Number(skills.reaction) || values[1] || 0;
  const throwingSkill = values[2] || 0;
  const armSkill = ["游擊手", "三壘手"].includes(effectivePosition) ? Number(skills.armStrength) || throwingSkill : throwingSkill;
  return Object.freeze({
    fielding: Math.round((values[0] * 2 + values[1] + (Number(subject.ballSense) || 0)) / 4),
    reaction: Math.round((reactionSkill * 2 + (Number(subject.ballSense) || 0)) / 3),
    range: Math.round(((Number(skills.range) || reactionSkill) * 2 + (Number(subject.fitness) || 0)) / 3),
    arm: Math.round((armSkill * 2 + (Number(subject.fitness) || 0)) / 3),
    throwing: Math.round((throwingSkill * 2 + (Number(subject.observe) || 0)) / 3),
    decision: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function resolveTiming(args){
  const {input,opportunity,selection,throwResolution:thrown,runnerState,receiverState}=args;
  Decision.validateSelection(selection,opportunity,input);
  if(!thrown||thrown.identity!==`${selection.identity}|throw-v1`||thrown.decisionIdentity!==selection.identity
    ||thrown.throwerId!==selection.defenderId||thrown.throwerPosition!==selection.position
    ||["routeId","targetRunnerId","targetBase","receiverId","receiverPosition"].some(key=>thrown[key]!==selection.route[key]))fail("stale throw / receiver / target");
  const base={version:VERSION,identity:`${thrown.identity}|timing-v1`,decisionIdentity:selection.identity,throwIdentity:thrown.identity,
    targetRunnerId:thrown.targetRunnerId,targetBase:thrown.targetBase,receiverId:thrown.receiverId,
    authority:"resolvedThrow+existingRunnerPhysicalState+receiverReadiness",variationEvidence:{consumed:false}};
  if(selection.route.action==="holdBall"){
    if(thrown.throwAttempted!==false)fail("hold includes throw");
    return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
      runnerArrival:null,ballArrival:null,receiverCompletion:null,reason:"heldBall"});
  }
  const current=(input.runnerPhysicalStates||[]).find(r=>r.runnerId===thrown.targetRunnerId);
  if(!current||!same(current,runnerState)||current.targetBase!==thrown.targetBase
    ||(current.originBase==="batter"?input.batterRunnerId!==current.runnerId:input.runners[Number(current.originBase)-1]!==current.runnerId))fail("stale runner physical state");
  const forced=Force.getForcedMovement(opportunity.context.forceChain,current.runnerId);
  if(!forced&&!Decision.isAdvancingTo(current,thrown.targetBase))fail("runner not in contest");
  if(!receiverState||receiverState.receiverId!==thrown.receiverId||!same(receiverState,input.receiverState))fail("stale receiver completion");
  const runnerArrival=deriveRunnerArrival(current);
  const noContest=!thrown.throwAttempted||thrown.throwQuality==="offline"||receiverState.ready!==true;
  const receiveDelay=Number(receiverState.receiveDelay??0),tagDelay=Number(receiverState.tagDelay??1);
  if(!Number.isFinite(receiveDelay)||receiveDelay<0||!Number.isFinite(tagDelay)||tagDelay<0)fail("invalid receiver delay");
  if(noContest)return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
    runnerArrival,ballArrival:{quality:thrown.throwQuality},receiverCompletion:{...clone(receiverState),status:"unavailableReceive"},reason:"unusableThrowOrReceiver"});
  const qualityDelay={onTarget:0,challengingReceive:1,lateWeakThrow:3}[thrown.throwQuality];
  if(qualityDelay===undefined)fail("generic timing cannot reinterpret legacy composite throw");
  const distanceDelay={short:0,medium:1,long:2}[thrown.throwDemand?.distanceClass];
  if(distanceDelay===undefined)fail("missing throw distance");
  const ballTime=4+distanceDelay+qualityDelay+(thrown.releaseQuality==="delayedRelease"?1:0);
  const completionTime=ballTime+receiveDelay;
  const margin=Math.round((runnerArrival.relativeArrival-completionTime)*1000)/1000;
  return freeze({...base,contestAvailable:true,timingClassification:classify(margin),timingMargin:margin,runnerArrival,
    ballArrival:{relativeArrival:ballTime,quality:thrown.throwQuality,releaseQuality:thrown.releaseQuality,distanceClass:thrown.throwDemand.distanceClass},
    receiverCompletion:{...clone(receiverState),status:thrown.throwQuality==="challengingReceive"?"challengedReceive":"readyReceive",
      relativeCompletion:completionTime,tagCompletion:completionTime+tagDelay},reason:"physicalArrivalComparison"});
}

function deriveSettlement(args){
  const {timing,input,opportunity,selection,resolveThirdOut}=args;
  if(!same(timing,resolveTiming(args)))fail("stale timing facts");
  const route=selection.route,hold=route.action==="holdBall",runner=timing.runnerArrival;
  const force=Force.getForcedMovement(opportunity.context.forceChain,route.targetRunnerId);
  const forced=Boolean(force&&force.targetBase===route.targetBase);
  if(!hold&&((route.forceType==="force"||route.forceType==="batterRunner")!==forced))fail("stale force semantics");
  const playType=hold?"hold":route.forceType==="batterRunner"?"batterRunner":forced?"force":"tag";
  const receiver=timing.receiverCompletion;
  const ahead=timing.contestAvailable&&timing.timingMargin>0; // Ties do not establish defense before arrival.
  const out=Boolean(ahead&&(playType==="tag"?receiver.tagAvailable===true&&receiver.tagCompletion<runner.relativeArrival:receiver.atBase===true));
  const runnersAfter=input.runners.slice(),movements=[],outIds=out?[route.targetRunnerId]:[],inTransit=[];
  const attempts=clone(args.scoringAttempts||[]);
  const known=new Set([...input.runners.filter(Boolean),input.batterRunnerId].filter(Boolean));
  if(new Set(attempts.map(a=>a.runnerId)).size!==attempts.length||attempts.some(a=>!known.has(a.runnerId)||a.runnerId===route.targetRunnerId))fail("invalid other scoring attempt");
  const contest=timing.contestAvailable&&!hold;
  if(contest){
    const origin=runnersAfter.indexOf(route.targetRunnerId);if(origin>=0)runnersAfter[origin]=null;
    if(!out&&route.targetBase==="home")attempts.push({runnerId:route.targetRunnerId,timing:"beforeThirdOut"});
    else if(!out){
      const index=["first","second","third"].indexOf(route.targetBase),occupant=runnersAfter[index];
      if(index<0)fail("invalid destination");
      if(occupant){
        const moving=Force.getForcedMovement(opportunity.context.forceChain,occupant);
        if(!moving)fail("destination occupied by a non-forced runner");
        inTransit.push(clone(moving));
      }
      runnersAfter[index]=route.targetRunnerId;
    }
    movements.push({runnerId:route.targetRunnerId,from:runner.originBase,to:out?"out":route.targetBase});
  }
  for(const attempt of attempts){const index=runnersAfter.indexOf(attempt.runnerId);if(index>=0)runnersAfter[index]=null;}
  const dp=route.action==="initiateDoublePlay";
  const continuation={status:hold?"heldBallAwaitRunnerContinuation":!contest?"liveBallRecoveryRequired":dp&&out?"secondLegPending":dp?"reassessAfterSafeFirstLeg":"liveBallContinuation",
    targetBase:dp&&out?"first":null,inTransitRunners:inTransit,
    pendingRunners:(input.runnerPhysicalStates||[]).filter(r=>r.runnerId!==route.targetRunnerId||!contest).map(clone)};
  return completeSettlement({identity:`${timing.identity}|settlement-v1`,timing,routeId:route.routeId,targetRunnerId:route.targetRunnerId,targetBase:route.targetBase,
    playType,runnerResult:hold?"held":!contest?"unresolved":out?"out":"safe",before:{outs:input.outs,runners:input.runners,scores:input.scores||null},
    runnersAfter,outIds,scoringAttempts:attempts,runnerMovement:movements,forceBefore:opportunity.context.forceChain,continuation,resolveThirdOut});
}

function resolveHighSchoolInfieldReceiver(situation, choice, sample, deliveryCompleted, match) {
  const position = choice.targetBase === "third" ? "3B" : choice.targetBase === "home" ? "C"
    : choice.targetBase === "second" || choice.targetBase === "secondThenFirst" ? "SS" : "1B";
  const legacy = position === "1B" ? situation.teammates?.firstBaseReceiver : position === "3B" ? situation.teammates?.thirdBaseReceiver
    : position === "C" ? situation.teammates?.catcher : situation.teammates?.shortstop;
  const actor = match?.rosters?.[match.defenseTeam] && typeof TeamRosterFoundation !== "undefined"
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], position) : null;
  const capabilities = actor ? getDefensiveSimulationCapability(actor, actor.position, match) : legacy?.capabilities || {};
  const fielding = Number(capabilities.fielding ?? 5), swing = (sample - .5) * 4;
  const available = Boolean((actor ? actor.id !== "player" : legacy) && legacy?.receivingAvailable !== false);
  const ready = available && fielding + swing >= 2.8;
  return Object.freeze({ receiverId: actor?.id || legacy?.id || null, receiverPosition: position, available, ready,
    secured: Boolean(deliveryCompleted && ready), status: !deliveryCompleted ? "notAttempted" : !available ? "unavailable" : ready ? "completed" : "failed",
    responsibleActor: deliveryCompleted && !ready ? "teammate" : "player",
    provenance: Object.freeze({ authority: actor ? "activeRosterReceiver+existingExecutionSample" : "declaredLegacyReceiver+existingExecutionSample",
      fielding, sample, swing, threshold: 2.8, consumedRng: false }) });
}

function sampleVector(physical, slot, samplerVersion = V.sampler) {
  try { dataOnly(physical); encode(physical); } catch (error) { return reject("invalidPhysicalIdentity"); }
  if (!physicalValid(physical)) return reject("invalidPhysicalIdentity");
  if (!["primaryThrow","relayThrow"].includes(slot)) return reject("unsupportedPhysicalSlot");
  if (samplerVersion !== V.sampler) return reject("unsupportedSampler");
  const stages = {};
  for (const stage of STAGES) {
    const key = { executionVersion: V.execution, physical, physicalSlot: slot, samplerVersion, stage };
    const canonical = encode(key), hash = sha256(canonical), u32 = parseInt(hash.slice(0,8),16);
    stages[stage] = { canonical, sha256: hash, u32, unit: (u32 + 0.5) / 4294967296 };
  }
  return freeze({ status: "ok", samplerVersion, stages });
}

function validate(input) {
  try {
    if (!object(input)) return reject("invalidInput");
    // Perform the canonical JSON check before any property-based schema reads.
    dataOnly(input);
    const copy = { ...input, ownedSample: input.ownedSample === undefined ? null : binary64(input.ownedSample) };
    encode(copy);
    if (!exact(input,["contractVersion","versions","identity","context","handoff","capabilities","ownedSample","delivery","positioning","secure","contest","provenance","effortReference","continuation"])) return reject("invalidInputSchema");
    if (input.contractVersion !== V.contract || !exact(input.versions,["execution","adapter","timing","sampler","effort"]) ||
      Object.keys(input.versions).some(k => input.versions[k] !== V[k])) return reject("unsupportedVersion");
    const i=input.identity, c=input.context, caps=input.capabilities;
    if (!exact(i,["playId","physical","leg","thrower","receiver","target"]) || !id(i.playId) || !physicalValid(i.physical)) return reject("invalidPhysicalIdentity");
    if (!exact(i.leg,["actionId","sourceThrowActionId","physicalSlot","parentActionId"]) || !id(i.leg.actionId) || !id(i.leg.sourceThrowActionId) ||
      !["primaryThrow","relayThrow"].includes(i.leg.physicalSlot) || (i.leg.physicalSlot === "primaryThrow" ? i.leg.parentActionId !== null : !id(i.leg.parentActionId))) return reject("invalidLegIdentity");
    if (![i.thrower,i.receiver].every(a => exact(a,["actorId","position"]) && id(a.actorId) && POSITIONS.includes(a.position)) || i.thrower.actorId === i.receiver.actorId) return reject("invalidActor");
    if (!exact(i.target,["runnerId","base"]) || !id(i.target.runnerId) || !BASES.includes(i.target.base) || [i.thrower.actorId,i.receiver.actorId].includes(i.target.runnerId)) return reject("invalidRunner");
    if (!exact(c,["initialOuts","originId","routeId","competitionLevel","environmentId","receiverAvailable"]) || !integer(c.initialOuts,0,2) ||
      ![c.originId,c.routeId,c.competitionLevel,c.environmentId].every(id) || typeof c.receiverAvailable !== "boolean") return reject("invalidContext");
    if (!exact(input.handoff,["playId","physicalIdentity","throwerId","receiverId","runnerId","base"]) ||
      encode(input.handoff) !== encode({playId:i.playId,physicalIdentity:i.physical.physicalIdentity,throwerId:i.thrower.actorId,receiverId:i.receiver.actorId,runnerId:i.target.runnerId,base:i.target.base})) return reject("handoffIdentityMismatch");
    if (!exact(caps,["actorId","adapterVersion","values"]) || caps.actorId !== i.receiver.actorId || caps.adapterVersion !== V.adapter ||
      !exact(caps.values,ABILITIES) || ABILITIES.some(k => !integer(caps.values[k],0,20))) return reject("invalidAbilitySnapshot");
    const d=input.delivery, p=input.positioning, s=input.secure, b=input.contest;
    if (!exact(d,["actionId","upstreamActionId","upstreamStatus","status","accuracy","quality","launch","ballArrival"]) ||
      d.actionId !== i.leg.sourceThrowActionId || !id(d.upstreamActionId) || !["completed","failed","notAttempted"].includes(d.upstreamStatus) ||
      !["completed","notAttempted"].includes(d.status) || !["onTarget","challenging","offline","none"].includes(d.accuracy) ||
      !["clean","challenging","none"].includes(d.quality) || !time(d.launch,c.originId) || !time(d.ballArrival,c.originId)) return reject("invalidDelivery");
    if (d.status === "completed" && (d.upstreamStatus !== "completed" || d.accuracy === "none" || d.quality === "none") ||
      d.status === "notAttempted" && (d.accuracy !== "none" || d.quality !== "none" || known(d.ballArrival)) ||
      d.accuracy === "onTarget" && d.quality !== "clean" || d.accuracy === "challenging" && d.quality !== "challenging") return reject("deliveryDependencyMismatch");
    if (known(d.launch) && known(d.ballArrival) && d.ballArrival.ticks < d.launch.ticks) return reject("arrivalBeforeLaunch");
    if (i.leg.physicalSlot === "primaryThrow" && known(d.launch) && d.launch.ticks !== 0) return reject("firstLaunchMustBeZero");
    if (!exact(p,["actionId","startContext","movementMdu","startTime"]) || !id(p.actionId) || !["atBase","covering","lateCover","distant"].includes(p.startContext) ||
      !integer(p.movementMdu,0,8) || !time(p.startTime,c.originId) || p.startContext === "atBase" && p.movementMdu !== 0) return reject("invalidPositioning");
    if (!exact(s,["actionId","demandMilli","cleanDelayTicks","bobbleDelayTicks"]) || s.actionId !== i.leg.actionId || !integer(s.demandMilli,0,30000) ||
      !integer(s.cleanDelayTicks,0,1000000) || !integer(s.bobbleDelayTicks,0,1000000)) return reject("invalidSecure");
    if (!exact(b,["actionId","type","attempted","contact","legality","delayTicks","runnerArrival"]) || !id(b.actionId) ||
      !["force","batterBeforeFirst","tag"].includes(b.type) || typeof b.attempted !== "boolean" || typeof b.contact !== "boolean" ||
      !integer(b.delayTicks,0,1000000) || !time(b.runnerArrival,c.originId,true) ||
      !exact(b.legality,["status","runnerId","base","sourceActionId"]) || !["eligible","ineligible","unknown"].includes(b.legality.status) ||
      b.legality.runnerId !== i.target.runnerId || b.legality.base !== i.target.base || !id(b.legality.sourceActionId) ||
      b.type === "batterBeforeFirst" && i.target.base !== "first") return reject("invalidContest");
    const actionIds=[d.actionId,p.actionId,s.actionId,b.actionId];
    if (new Set(actionIds).size !== actionIds.length || actionIds.includes(d.upstreamActionId)) return reject("duplicateActionIdentity");
    if (!exact(input.provenance,SOURCES) || SOURCES.some(k => !source(input.provenance[k]))) return reject("missingOrInvalidProvenance");
    const missing=SOURCES.filter(k => input.provenance[k].classification === "C");
    if (missing.length) return reject("insufficientExecutionSources",missing,"insufficient");
    if (input.effortReference !== null) {
      const e=input.effortReference;
      if (!exact(e,["version","status","position","competitionLevel","environmentId","referenceId","capabilities","provenance"]) ||
        e.version !== V.effort || !["uncalibrated","calibrated"].includes(e.status) || e.position !== i.receiver.position ||
        e.competitionLevel !== c.competitionLevel || e.environmentId !== c.environmentId || !id(e.referenceId) ||
        !exact(e.capabilities,ABILITIES) || ABILITIES.some(k=>!integer(e.capabilities[k],0,20)) || !source(e.provenance)) return reject("invalidEffortReference");
      // Calibration authority is intentionally not implemented in this pure sprint.
      if (e.status === "calibrated") return reject("unavailableCalibrationAuthority",[],"insufficient");
    }
    if (i.leg.physicalSlot === "primaryThrow" && input.continuation !== null) return reject("unexpectedContinuation");
    if (i.leg.physicalSlot === "relayThrow") {
      const q=input.continuation;
      if (!exact(q,["firstRetirement","pivot","provenance"]) || !source(q.provenance)) return reject("missingContinuation",[],"insufficient");
      if (q.provenance.classification === "C") return reject("insufficientContinuation",[],"insufficient");
      if (!exact(q.firstRetirement,["status","actionId","runnerId","base","outsBefore","outsAfter"]) ||
        !["completed","failed"].includes(q.firstRetirement.status) || ![q.firstRetirement.actionId,q.firstRetirement.runnerId].every(id) ||
        !BASES.includes(q.firstRetirement.base) || !integer(q.firstRetirement.outsBefore,0,2) || !integer(q.firstRetirement.outsAfter,0,3) ||
        !exact(q.pivot,["status","actorId","actionId"]) || !["completed","failed","notAttempted"].includes(q.pivot.status) ||
        q.pivot.actorId !== i.thrower.actorId || !id(q.pivot.actionId)) return reject("invalidContinuation");
    }
    return freeze({status:"ok"});
  } catch (error) { return reject("noncanonicalInput",[String(error.message)]); }
}

function getCurrentDefender(roster, position) {
  if (!validateActiveDefense(roster).ok) return null;
  const code = normalizePosition(position);
  return roster.lineup.find(actor => normalizePosition(actor.defensivePosition || actor.position) === code) || null;
}
